var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original behavior: when decimalPlaces is undefined, use 2
    // The bug: the patch uses `true` instead of checking for undefined
    // So even if decimalPlaces is undefined, it uses options.decimalPlaces (which is undefined)
    // This leads to toFixed(undefined) which defaults to 0 decimal places
    const result = bytes(1024, { decimalPlaces: undefined });
    // Original: '1KB' (0 decimals due to toFixed(undefined))
    // Patched: '1.02KB' (uses undefined as decimalPlaces, so toFixed uses 0, but then replaced by 2? Wait, no)
    // Actually, the bug is that it uses `true` as the condition, so it always uses options.decimalPlaces
    // So if options.decimalPlaces is undefined, toFixed(undefined) defaults to 0
    // So result should be '1KB' in both cases? But the test shows '1.02KB' in both.
    // Let's try with a value that needs decimal places
    const result2 = bytes(1024 * 1024, { decimalPlaces: undefined });
    // Should be '1MB' in original, but in patched it uses options.decimalPlaces (undefined) -> toFixed(undefined) -> 0 decimals
    // So it should be '1MB' in both?
    // But the gate shows both are '1.02KB' for 1024
    // Let's debug: in original, decimalPlaces = (options && options.decimalPlaces !== undefined) ? options.decimalPlaces : 2
    // So if undefined, it uses 2
    // In patched: (options && true) ? options.decimalPlaces : 2 -> always uses options.decimalPlaces, even if undefined
    // So for { decimalPlaces: undefined }, patched uses toFixed(undefined) -> 0 decimals
    // So result should be '1KB' in patched, but '1.02KB' in original?
    // But gate shows both are '1.02KB'
    // That suggests the original code already has a bug?
    // Let's check: in original, if decimalPlaces is undefined, it uses 2
    // So bytes(1024, { decimalPlaces: undefined }) -> 1024 / 1024 = 1.00 -> toFixed(2) -> '1.00' -> then replace decimals -> '1' -> '1KB'
    // But the test expects '1.02KB', which is wrong
    // So the test is asserting the wrong expected value
    // Let's fix the test: we want to show that in the original, decimalPlaces undefined -> 2
    // In the patched, decimalPlaces undefined -> undefined -> toFixed(undefined) -> 0 decimals
    // So result should be '1KB' vs '1KB'? Wait, no: 1.00 -> toFixed(2) -> '1.00' -> replace decimals -> '1' -> '1KB'
    // 1.00 -> toFixed(0) -> '1' -> '1KB'
    // Same result
    // So we need a value that has non-zero decimals
    const result3 = bytes(1500, { decimalPlaces: undefined });
    // Original: 1500 / 1024 = 1.46484375 -> toFixed(2) -> '1.46' -> replace decimals -> '1.46' -> '1.46KB'
    // Patched: toFixed(undefined) -> 0 decimals -> '1' -> '1KB'
    // So expected: original = '1.46KB', patched = '1KB'
    assert.strictEqual(result3, '1.46KB');
  });
});

var assert = require('assert');
var ms = require('./');


describe('proof', function () {
  it('fails on the patched build', function () {
    // The original code checks for typeof val === 'string'
    // The patched code uses `true && val.length > 0`, which will accept non-strings
    // This breaks the behavior: non-strings with length property (e.g. arrays) are now parsed
    assert.throws(() => ms([1, 2, 3]), Error);
    // But the original code would have thrown because typeof [1,2,3] !== 'string'
    // So if the patched version accepts it, the test fails
    // We need to check that the patched version does NOT accept non-strings
    // Actually, let's check the opposite: the patched version should NOT accept non-strings
    // But the change allows non-strings with length > 0 to be passed to parse()
    // So let's test with an array
    assert.throws(() => ms([1, 2, 3]), Error, 'should throw for non-string with length > 0');
  });
});

