var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The original behavior was to interpret '1y' as 1 year in milliseconds
    // i.e., 365.25 * 24 * 60 * 60 * 1000 milliseconds
    // The change swapped * to /, so now it returns 1 / 365.25 years in seconds
    // This is clearly wrong: 1 year should be a large number of milliseconds
    // The test should fail on the patched version (which returns a tiny number)
    // and pass on the original (which returns ~31.5 million milliseconds)
    assert.strictEqual(ms('1y'), 1000 * 60 * 60 * 24 * 365.25);
    assert.strictEqual(ms('2y'), 2 * 1000 * 60 * 60 * 24 * 365.25);
  });
});
